func extractHiddenInputs(html, name string) []string {
	var out []string
	marker := `name="` + name + `" value="`
	for rest := html; ; {
		i := strings.Index(rest, marker)
		if i < 0 {
			return out
		}
		rest = rest[i+len(marker):]
		j := strings.Index(rest, `"`)
		out = append(out, rest[:j])
		rest = rest[j:]
	}
}
